"""BPF C code generator.

Given an analyzed AST, emits a C source string that clang compiles to
a verifier-accepted XDP program. Bounds checks at every layer; IPv4
IHL handled correctly; TCP/UDP ports in host byte order.

Phase 0 emits the minimum viable XDP program: a single function with
SEC("xdp") returning XDP_PASS or XDP_DROP based on the first rule.
The emitted code does no packet parsing yet — that lands when the
first rule with a `pkt.*` field access shows up.
"""
from __future__ import annotations

from . import ast


_HEADER = """\
// Generated by fwl. Do not edit.

#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>

#define XDP_PASS 2
#define XDP_DROP 1
"""


_ACTION_TO_RETURN = {
  ast.Action.ALLOW: "XDP_PASS",
  ast.Action.DROP: "XDP_DROP",
}


def emit(program: ast.Program) -> str:
  """Emit BPF C source for `program`.

  Returns the source as a string. Caller is responsible for invoking
  clang to produce object code.
  """
  if program.rules:
    first_action = program.rules[0].action
    body_return = _ACTION_TO_RETURN[first_action]
  else:
    body_return = "XDP_PASS"

  return f"""{_HEADER}
SEC("xdp")
int fwl_prog(struct xdp_md *ctx) {{
  return {body_return};
}}

char _license[] SEC("license") = "GPL";
"""
